cd /home/axel/LeanAlgebraicGeometry-Horizon && python3 - <<'EOF'
import json
for n in ['AJC.jacobian.assembly','AJC.picrep']:
    print('='*70, n)
    try:
        ls=open('.archon-horizon/roadmap/history/%s.jsonl'%n).read().strip().split('\n')
    except FileNotFoundError:
        print('no history'); continue
    for l in ls[-4:]:
        e=json.loads(l)
        pv=e.get('provenance') or {}
        print(str(e.get('at'))[:19], e.get('field'), repr(e.get('from'))[:40],'->',repr(e.get('to'))[:60], '| run',pv.get('run'),'task',pv.get('task'))
EOF

